import { HttpErrorResponse } from '@angular/common/http';
import { Component, OnInit, SecurityContext } from '@angular/core';
import { EmailValidator, FormControl, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import jwt_decode from 'jwt-decode';
import { CookieService } from 'ngx-cookie';
import { UserService } from '../../services/user.service';
import { AlertConfig } from 'ngx-bootstrap/alert';
import * as CryptoJS from 'crypto-js';  



@Component({
  selector: 'app-login',
  templateUrl: 'login.component.html',
  styleUrls: ['./login.component.css'],
  providers: [{ provide: AlertConfig }]

})
export class LoginComponent implements OnInit {
  userName = '';
  condition = this.userName.length == 6
  constructor(private userservice: UserService, private router: Router,
    private cookieService: CookieService) {

  }

  ngOnInit(): void {

    localStorage.clear();
   }

  loginForm = new FormGroup(
    {
      username: new FormControl('',),
      password: new FormControl('',),
    })
  get username() {
    return this.loginForm.get('username') as FormControl;
  }

  get password() {
    return this.loginForm.get('password') as FormControl;
  }
  decoded: any;

  login() {
    if (this.loginForm.valid) {
      let element: HTMLElement = document.getElementById('password') as HTMLElement;
      element.className = "form-control"
      let element2: HTMLElement = document.getElementById('username') as HTMLElement;
      element2.className = "form-control"
      this.userservice.login(this.loginForm.value).subscribe(
        data => {
          this.cookieService.put('token', data.access_token);
          this.decoded = jwt_decode(data.access_token);
          localStorage.setItem('current_user_id', this.decoded.sub)
          if (this.decoded.roles == "admin")
            this.router.navigateByUrl('dashboard');
          else
          {this.alertsDismiss=[];
            this.cookieService.remove("token");
            localStorage.clear();
            this.warning()
          }
        },

        (error: HttpErrorResponse) => {
          if (error.status == 401) {
            this.alertsDismiss=[];
            this.add()
          }
         
        }
      )
    }

    else {
      var password = (<HTMLInputElement>document.getElementById("password")).value;
      var username = (<HTMLInputElement>document.getElementById("username")).value;
      if (password == "") {
        let element: HTMLElement = document.getElementById('password') as HTMLElement;
        element.className = element.className + " is-invalid"
      }
      if (username == "") {
        let element2: HTMLElement = document.getElementById('username') as HTMLElement;
        element2.className = element2.className + " is-invalid"
      }
    }

  }

  alertsDismiss: any = [];
  add(): void {
    this.alertsDismiss.push({
      type: 'danger',
      msg: `Invalid username or password`,
      timeout: 5000
    });
  }

  warning(): void {
    this.alertsDismiss.push({
      type: 'warning',
      msg: `You dont have permission to pass`,
      timeout: 5000
    });
  }

  //  copy paste section 

  email_section = true;
  code_section = false;
  password_section = false;
  mdp = ""
  alertsDismiss1: any = [];
  change_success(msg: string): void {
    this.alertsDismiss.push({
      type: 'success',
      msg: msg,
      timeout: 5000
    });
  }
  bad_email(msg: string): void {
    this.alertsDismiss1=[];
    this.alertsDismiss1.push({
      type: 'danger',
      msg: "email " + msg,
      timeout: 3000
    });
  }
  cancel_change() {
    let element: HTMLElement = document.getElementById('close') as HTMLElement;
    element.click();
    this.email_section = true;
    this.code_section = false;
    this.password_section = false;
    this.code = "";
    this.email = ""

  }

  hide() { }
  email = "";


  open_model() {
    this.cancel_change();
  }


  email_group = new FormGroup(
    {
      email_filed: new FormControl('', Validators.email),
    })
  /* get email() {
     return this.email_group.get('email_filed') as FormControl;
   }
 */
   conversionEncryptOutput:any
   code_email=""
  pass() {
      this.userservice.check_email(this.email).subscribe(
        (response: any) => {

          if (response.body.result == "not found")
            this.bad_email(response.body.result);
          else {
            this.code_email=response.body.result;
            this.email_section = false;
            this.code_section = true;
            this.conversionEncryptOutput = CryptoJS.AES.encrypt(this.code_email,"secure_code").toString();
            localStorage.setItem("code",this.conversionEncryptOutput)
          }  
          
        },
        (error: HttpErrorResponse) => {
          console.log(error)
        }
      )
  }

  code_decrypt="";
  code=""
  code_correct = true;
  verif_code() {

    this.code_decrypt=CryptoJS.AES.decrypt(localStorage.getItem('code'),"secure_code").toString(CryptoJS.enc.Utf8);  
   if (this.code == this.code_decrypt)
   {
    this.code_section = false;
    this.password_section = true;
   }
   else
   {
     this.code_correct=false;
   } 
  }

  confirm_password = true;
  msg_success: any;
  loginuser: any;
  change_password() {
    var new_mdp = (<HTMLInputElement>document.getElementById("new_mdp")).value;
    var confirm_mdp = (<HTMLInputElement>document.getElementById("confirm_mdp")).value;
    if (new_mdp != confirm_mdp) {
      this.confirm_password = false;
      let element: HTMLElement = document.getElementById('confirm_mdp') as HTMLElement;
      element.className = element.className + " is-invalid"
    }
    else {
      this.confirm_password = true;
      let element: HTMLElement = document.getElementById('confirm_mdp') as HTMLElement;
      element.className = "form-control"
      this.userservice.change_pw_email(this.email, new_mdp).subscribe(
        (response: any) => {
          this.cancel_change()
          this.change_success(response.result)
        },
        (error: HttpErrorResponse) => {
          if (error.status == 403) {
            localStorage.clear();
            this.userservice.clear();
            this.router.navigateByUrl('/login');

          }
        }
      )
    }
  }
}

