import { Injectable } from '@angular/core';
import {HttpClient, HttpHeaders} from '@angular/common/http'
import { Observable } from 'rxjs';
import { CookieService } from 'ngx-cookie';
import { environment } from '../../environments/environment';


@Injectable({
  providedIn: 'root'
})
export class UserService {
  private baseurl = environment.baseurl;

  constructor( private  http :HttpClient , private cookie : CookieService ) { }

 
  public login( obj :any) :Observable<any>
  {
    const formData = new FormData();
    formData.append('username',obj.username);
    formData.append('password',obj.password)
    return  this.http.post(this.baseurl+`login`,formData,{ responseType : 'json' })
  }

  public get_all_users():Observable<any>
  {
    return this.http.get(this.baseurl+'user/all' ,{observe: 'response'});
  }


  public get_interrogator(loginuser : String):Observable<any>
  {
    return this.http.get(this.baseurl+`user/interrogator/`+loginuser);
  }

  public save(loginuser : String , obj :any):Observable<any>
  {
    return this.http.post(this.baseurl+'user/register/'+loginuser,obj,{observe: 'response'});
  }
  
  public get_user(loginuser :string):Observable<any>
  {
    return this.http.get(this.baseurl+"user/"+loginuser);
  }

  public verif_pass(loginuser:string,mdp:string) 
  {
    return this.http.post(this.baseurl+"user/verif/pass/"+loginuser+"/"+mdp,{observe: 'response'})
  }

public change_mdp(loginuser:string,mdp:string) 
{
  return this.http.put(this.baseurl+"user/update/pw/"+loginuser+"/"+mdp,{observe: 'response'})
}

public check_email(email :string)
{
  return this.http.get("http://lesionia.pasteur.tn:7000/free/verif_email/"+email,{observe: 'response'});
}

public change_pw_email(email :string ,pw :string)
{
  return this.http.post("http://lesionia.pasteur.tn:7000/free/change_pw/"+email+"/"+pw,{observe: 'response'})
}


public update(obj :any):Observable<any>
{
  return this.http.put(this.baseurl+"user/",obj,{observe: 'response'})
}

public delete(loginuser:string):Observable<any>
{
  return this.http.delete(this.baseurl+"user/"+loginuser,{observe: 'response'})
}


  islogged()
  { 
    return !! this.cookie.get('token');
  }


  clear()
  {
    this.cookie.remove('token');
  }
}
